import{_ as e,c as o,o as s,ae as r}from"./chunks/framework.CHDT0Kbg.js";const p=JSON.parse('{"title":"Preguntas frecuentes","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/faq.md","filePath":"es/guide/faq.md","lastUpdated":1795170900000}'),t={name:"es/guide/faq.md"};function n(i,a,d,c,u,l){return s(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="preguntas-frecuentes" tabindex="-1">Preguntas frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas frecuentes&quot;">​</a></h1><p>Respuestas rápidas sobre Persim.</p><h3 id="¿es-gratis" tabindex="-1">¿Es gratis? <a class="header-anchor" href="#¿es-gratis" aria-label="Permalink to &quot;¿Es gratis?&quot;">​</a></h3><p>Puedes descargarlo y usar las funciones básicas sin pagar. Algunas funciones avanzadas se desbloquean con una compra integrada, y la versión gratuita muestra una pequeña insignia en la barra de pestañas.</p><h3 id="¿que-sistemas-operativos-son-compatibles" tabindex="-1">¿Qué sistemas operativos son compatibles? <a class="header-anchor" href="#¿que-sistemas-operativos-son-compatibles" aria-label="Permalink to &quot;¿Qué sistemas operativos son compatibles?&quot;">​</a></h3><p>Persim está pensado para macOS 12 o posterior y funciona en Macs con Apple Silicon e Intel.</p><h3 id="¿se-suben-mis-datos" tabindex="-1">¿Se suben mis datos? <a class="header-anchor" href="#¿se-suben-mis-datos" aria-label="Permalink to &quot;¿Se suben mis datos?&quot;">​</a></h3><p>No hace falta cuenta: el historial, los marcadores, las sesiones y las descargas se quedan en tu Mac. Solo las funciones que necesitan red —como actualizar una suscripción— se conectan a Internet.</p><h3 id="¿como-importo-marcadores-de-otro-navegador" tabindex="-1">¿Cómo importo marcadores de otro navegador? <a class="header-anchor" href="#¿como-importo-marcadores-de-otro-navegador" aria-label="Permalink to &quot;¿Cómo importo marcadores de otro navegador?&quot;">​</a></h3><p>Exporta los marcadores a HTML desde Chrome o Edge y usa «Importar HTML» en el gestor de marcadores de Persim. Las carpetas y los enlaces duplicados se tratan automáticamente.</p><h3 id="¿como-guardo-un-video" tabindex="-1">¿Cómo guardo un vídeo? <a class="header-anchor" href="#¿como-guardo-un-video" aria-label="Permalink to &quot;¿Cómo guardo un vídeo?&quot;">​</a></h3><p>Abre el panel multimedia, elige un vídeo detectado y descárgalo. Las partes se unen en un MP4 que puedes abrir con tu aplicación habitual.</p><h3 id="¿como-cambio-el-idioma" tabindex="-1">¿Cómo cambio el idioma? <a class="header-anchor" href="#¿como-cambio-el-idioma" aria-label="Permalink to &quot;¿Cómo cambio el idioma?&quot;">​</a></h3><p>Ve a <code>persim://settings</code> → <strong>General</strong> → <strong>Idioma</strong>. Hay 25 idiomas; vuelve a abrir la ventana para ver el cambio.</p><h3 id="¿mas-preguntas" tabindex="-1">¿Más preguntas? <a class="header-anchor" href="#¿mas-preguntas" aria-label="Permalink to &quot;¿Más preguntas?&quot;">​</a></h3><p>Escribe a <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong> y cuéntanos qué querías hacer.</p>',16)])])}const h=e(t,[["render",n]]);export{p as __pageData,h as default};
